from strings_student import STUDENT  # noqa: E402

for key, value in STUDENT.items():
    assert key not in STRINGS or STRINGS[key] == value, f"duplicate key with another text: {key}"
    STRINGS[key] = value

HEADER = """<?xml version="1.0" encoding="utf-8"?>
<root>
  <resheader name="resmimetype"><value>text/microsoft-resx</value></resheader>
  <resheader name="version"><value>2.0</value></resheader>
  <resheader name="reader"><value>System.Resources.ResXResourceReader, System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089</value></resheader>
  <resheader name="writer"><value>System.Resources.ResXResourceWriter, System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089</value></resheader>
"""


def read(path: Path) -> dict:
    if not path.exists():
        return {}
    root = ET.parse(path).getroot()
    return {d.get("name"): (d.findtext("value") or "") for d in root.findall("data")}


def main() -> None:
    for i, lang in enumerate(ORDER):
        path = ROOT / FILES[lang]
        values = {k: v for k, v in read(path).items() if k not in REMOVE}
        values.update({k: v[i] for k, v in STRINGS.items()})
        body = "".join(f'  <data name="{escape(k)}" xml:space="preserve"><value>{escape(v)}</value></data>\n' for k, v in values.items())
        path.write_text(HEADER + body + "</root>\n", encoding="utf-8")
        print(f"{FILES[lang]}: {len(values)} strings")


if __name__ == "__main__":
    for key, value in STRINGS.items():
        assert len(value) == 4, key
    main()
